.include "zelda2.inc"

.segment "BANK6"


; ---------------------------------------------------------------------------
; Sound_TitleEngine
;
; The title screen's sound engine, run every frame by Sound_UpdateTitle:
; sound effects (TitleSfx_Update) and music (TitleMusic_Update), then clear
; the requests.  It uses the gameplay engine's RAM under other names
; (the title* overlays in ram.inc).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sound_TitleEngine:
    lda     #$FF                    ; $8000  the frame counter: 4-step, no IRQ
    sta     APU_FRAME               ; $8002
    lda     #$0F                    ; $8005  pulses, triangle and noise on
    sta     SND_CHN                 ; $8007
    jsr     TitleSfx_Update         ; $800A  the effects,
    jsr     TitleMusic_Update       ; $800D  then the music
    lda     #$00                    ; $8010  this frame's requests are done
    sta     titleSfxRequest         ; $8012
    sta     titleSongRequest        ; $8014
    rts                             ; $8016
; (unreferenced: $8017-$8046, 48 bytes)

TitleEnvelopes:
    .byte   $90, $90, $91, $91, $92, $92, $93, $93, $94, $94, $95, $95, $96, $96, $97, $97; $8017
    .byte   $98, $98, $99, $99, $9A, $9A, $9B, $9C, $50, $50, $51, $51, $52, $52, $53, $53; $8027
    .byte   $54, $54, $55, $55, $56, $56, $57, $57, $58, $58, $59, $59, $5A, $5A, $5B, $5C; $8037
    .byte   $90, $90, $90, $90, $90, $90, $90, $90, $91, $92, $93, $94, $95, $96, $97, $98; $8047
    .byte   $99, $9A, $9B, $9C, $9D, $9E                                    ; $8057

TitleDrums:
    .byte   $9F, $9F, $1B, $03, $48, $00, $17, $06, $38, $00, $18, $08, $38, $00, $17, $0A; $805D
    .byte   $38, $00, $15, $07, $98, $00, $10                               ; $806D

TitleSfxVolumes:
    .byte   $D0, $51, $D2, $53, $D4, $55, $D6, $57, $D8, $59, $DA, $5B, $DC, $5D, $DE, $5F; $8074

TitleNoteLengths:
    .byte   $08, $18, $10, $20, $30, $40, $60, $80, $0B, $0A, $50           ; $8084

TitlePeriods:
    .byte   $00, $00, $00, $00, $06, $AE, $06, $4E, $05, $F3, $05, $9E, $05, $4D, $05, $02; $808F
    .byte   $04, $B9, $04, $75, $04, $35, $03, $F8, $03, $BF, $03, $89, $03, $57, $03, $27; $809F
    .byte   $02, $F9, $02, $CF, $02, $A6, $02, $80, $02, $5C, $02, $3A, $02, $1A, $01, $FC; $80AF
    .byte   $01, $DF, $01, $C4, $01, $AB, $01, $93, $01, $7C, $01, $67, $01, $52, $01, $3F; $80BF
    .byte   $01, $2D, $01, $1C, $01, $0C, $00, $FD, $00, $EE, $00, $E1, $00, $D4, $00, $C8; $80CF
    .byte   $00, $BD, $00, $B2, $00, $A8, $00, $9F, $00, $96, $00, $8D, $00, $85, $00, $7E; $80DF
    .byte   $00, $76, $00, $70, $00, $6A, $00, $64, $00, $5F, $00, $59, $00, $54, $00, $50; $80EF
    .byte   $00, $4B, $00, $47, $00, $43, $00, $3F, $00, $3B, $00, $38, $00, $35, $00, $32; $80FF

; ---------------------------------------------------------------------------
; TitleSq1_SetEnvelope
;
; Write x to SQ1_VOL and y to SQ1_SWEEP.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq1_SetEnvelope:
    stx     SQ1_VOL                 ; $810F
    sty     SQ1_SWEEP               ; $8112
    rts                             ; $8115

; ---------------------------------------------------------------------------
; TitleSq2_SetEnvelope
;
; Write x to SQ2_VOL and y to SQ2_SWEEP.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq2_SetEnvelope:
    stx     SQ2_VOL                 ; $8116
    sty     SQ2_SWEEP               ; $8119
    rts                             ; $811C
; (unreferenced: $811D-$811F, 3 bytes)
    .byte   $20, $0F, $81                                                   ; $811D

; ---------------------------------------------------------------------------
; TitleSq1_PlayNote
;
; Play pitch a (an even TitlePeriods index) on pulse 1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq1_PlayNote:
    ldx     #$00                    ; $8120

; ---------------------------------------------------------------------------
; TitleSound_PlayNote
;
; Play pitch a (0 = rest) on the channel at x (0 pulse 1, 4 pulse 2, 8
; triangle), keeping a pulse's timer low byte for its vibrato.  The title
; engine's copy of Sound_PlayNote.
;
; In:      a = pitch, x = channel register offset
; Out:     z set for a rest
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSound_PlayNote:
    tay                             ; $8122
    lda     TitlePeriods+1,y        ; $8123  the period's low byte
    beq     @done                   ; $8126  0: a rest
    sta     SQ1_LO,x                ; $8128
    cpx     #$00                    ; $812B  pulse 1:
    bne     @checkSq2               ; $812D
    sta     titleSq1TimerLo         ; $812F  kept for its vibrato
    bne     @high                   ; $8132

@checkSq2:
    cpx     #$04                    ; $8134  pulse 2:
    bne     @high                   ; $8136
    sta     titleSq2TimerLo         ; $8138  kept

@high:
    lda     TitlePeriods,y          ; $813B  the high bits,
    ora     #$08                    ; $813E  with a length counter load
    sta     SQ1_HI,x                ; $8140  (restarts the note)

@done:
    rts                             ; $8143
; (unreferenced: $8144-$8146, 3 bytes)
    .byte   $20, $16, $81                                                   ; $8144

; ---------------------------------------------------------------------------
; TitleSq2_PlayNote
;
; Play pitch a on pulse 2.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq2_PlayNote:
    ldx     #$04                    ; $8147
    bne     TitleSound_PlayNote     ; $8149

; ---------------------------------------------------------------------------
; TitleTri_PlayNote
;
; Play pitch a on the triangle.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleTri_PlayNote:
    ldx     #$08                    ; $814B
    bne     TitleSound_PlayNote     ; $814D

; ---------------------------------------------------------------------------
; TitleMusic_NoteLength
;
; Note length for a length byte: TitleNoteLengths[titleDurationBase + low
; nybble].
;
; In:      a = length byte
; Out:     a = frames
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_NoteLength:
    and     #$0F                    ; $814F  the length index
    clc                             ; $8151
    adc     titleDurationBase       ; $8152  in the phrase's row
    tay                             ; $8155
    lda     TitleNoteLengths,y      ; $8156  frames
    rts                             ; $8159

; ---------------------------------------------------------------------------
; TitleSq1_VibratoSfx
;
; Vibrato on pulse 1 for a title sound effect: the period's low byte is
; the note's (titleSq1TimerLo) + 2 or - 2 by bit 2 of the effect's frames
; left (titleSfxTimer), so it wavers every 4 frames.  TitleSq1_Vibrato
; uses pulse 1's note timer instead; the fall-through to it never happens
; (the timer is nonzero while an effect plays).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq1_VibratoSfx:
    lda     titleSfxTimer           ; $815A  an effect playing?
    bne     TitleSq1_VibratoA       ; $815C

TitleSq1_Vibrato:
    lda     titleSq1Timer           ; $815E  the note's frames left

TitleSq1_VibratoA:
    ldx     #$00                    ; $8160  pulse 1, from its base
    ldy     titleSq1TimerLo         ; $8162
    bne     TitleSound_Vibrato      ; $8165

; ---------------------------------------------------------------------------
; TitleSq2_VibratoSfx
;
; Vibrato on pulse 2 for a title sound effect, as TitleSq1_VibratoSfx (from
; titleSq2TimerLo); TitleSq2_Vibrato uses pulse 2's note timer.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSq2_VibratoSfx:
    lda     titleSfxTimer           ; $8167  an effect playing?
    bne     TitleSq2_VibratoA       ; $8169

TitleSq2_Vibrato:
    lda     titleSq2Timer           ; $816B  the note's frames left

TitleSq2_VibratoA:
    ldx     #$04                    ; $816D  pulse 2, from its base
    ldy     titleSq2TimerLo         ; $816F

; ---------------------------------------------------------------------------
; TitleSound_Vibrato
;
; The title engine's copy of Sound_Vibrato.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSound_Vibrato:
    sty     titleVibratoBase        ; $8172  (titleMusicPart is free scratch here)
    lsr     a                       ; $8175  bit 2 of the frames left:
    lsr     a                       ; $8176
    lsr     a                       ; $8177
    bcs     @up                     ; $8178
    lda     #$FE                    ; $817A  clear: base - 2
    clc                             ; $817C
    adc     titleVibratoBase        ; $817D
    bne     @store                  ; $8180

@up:
    lda     #$02                    ; $8182  set: base + 2
    clc                             ; $8184
    adc     titleVibratoBase        ; $8185

@store:
    sta     SQ1_LO,x                ; $8188  the low byte only
    rts                             ; $818B

; ---------------------------------------------------------------------------
; TitleSfx_Start
;
; Make y the playing effect (titleSfx) for a frames, and zero the music's
; pulse and echo envelope steps.
;
; In:      a = frames, y = effect
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSfx_Start:
    sty     titleSfx                ; $818C  the effect,
    sta     titleSfxTimer           ; $818E  its frames
    lda     #$00                    ; $8190  the music's envelopes restart after
    sta     titleSq2EnvStep         ; $8192
    sta     titleEchoEnvStep        ; $8195
    sta     titleSq1EnvStep         ; $8198
    rts                             ; $819B

TitleSfx_NameCursor:
    lda     #$0C                    ; $819C  $0C frames
    jsr     TitleSfx_Start          ; $819E
    ldx     #$88                    ; $81A1  both pulses' envelope
    ldy     #$7F                    ; $81A3
    jsr     TitleSq1_SetEnvelope    ; $81A5
    jsr     TitleSq2_SetEnvelope    ; $81A8
    lda     #$56                    ; $81AB  pitch $56,
    bne     TitleSfx_PlayTone       ; $81AD

TitleSfx_NameCursorStep:
    lda     titleSfxTimer           ; $81AF  then at 8 left:
    cmp     #$08                    ; $81B1
    bne     @check4                 ; $81B3
    lda     #$5E                    ; $81B5  $5E,
    bne     TitleSfx_PlayTone       ; $81B7

@check4:
    cmp     #$04                    ; $81B9  at 4 left:
    bne     TitleSfx_VibratoFar     ; $81BB
    lda     #$64                    ; $81BD  $64

TitleSfx_PlayTone:
    jsr     TitleSq1_PlayNote       ; $81BF  on pulse 1
    tya                             ; $81C2  (y: the pitch)
    jsr     TitleSq2_PlayNote       ; $81C3  and pulse 2

TitleSfx_VibratoFar:
    jmp     TitleSfx_Vibrato        ; $81C6

TitleSfx_LetterCursor:
    lda     #$06                    ; $81C9  6 frames
    jsr     TitleSfx_Start          ; $81CB
    ldx     #$9F                    ; $81CE  timer low $71
    ldy     #$7F                    ; $81D0
    lda     #$71                    ; $81D2
    bne     TitleSfx_StartTone      ; $81D4

TitleSfx_Select:
    lda     #$06                    ; $81D6  6 frames
    jsr     TitleSfx_Start          ; $81D8
    ldx     #$9F                    ; $81DB  timer low $A9
    ldy     #$7F                    ; $81DD
    lda     #$A9                    ; $81DF

TitleSfx_StartTone:
    jsr     TitleSq1_SetEnvelope    ; $81E1  both pulses' envelope
    jsr     TitleSq2_SetEnvelope    ; $81E4
    sta     SQ1_LO                  ; $81E7  pulse 1 at the timer low,
    sta     titleSq1TimerLo         ; $81EA
    sec                             ; $81ED
    sbc     #$02                    ; $81EE  pulse 2 2 lower
    sta     SQ2_LO                  ; $81F0
    sta     titleSq2TimerLo         ; $81F3
    lda     #$08                    ; $81F6  high 0, length counter load
    sta     SQ1_HI                  ; $81F8
    sta     SQ2_HI                  ; $81FB

TitleSfx_Vibrato:
    jsr     TitleSq1_VibratoSfx     ; $81FE  both waver
    jsr     TitleSq2_VibratoSfx     ; $8201

TitleSfx_Tick:
    dec     titleSfxTimer           ; $8204  count down:
    bne     @done                   ; $8206
    lda     #$00                    ; $8208  over:
    sta     titleSfx                ; $820A
    lda     #$10                    ; $820C  both pulses silent
    sta     SQ1_VOL                 ; $820E
    sta     SQ2_VOL                 ; $8211

@done:
    rts                             ; $8214

TitleSfx_NameCursorFar:
    jmp     TitleSfx_NameCursor     ; $8215

TitleSfx_NameCursorStepFar:
    jmp     TitleSfx_NameCursorStep ; $8218

; ---------------------------------------------------------------------------
; TitleSfx_Update
;
; Start or continue a title sound effect (titleSfxRequest; titleSfx while
; one plays), on both pulse channels: bit 0 TitleSfx_NameCursor (A or B on
; the name screen), bit 1 TitleSfx_LetterCursor (moving over the letters),
; bit 2 TitleSfx_Select (SELECT), bit 3 TitleSfx_Eliminate (a file
; eliminated).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleSfx_Update:
    ldy     titleSfxRequest         ; $821B  the requests (y: the effect started)
    lda     titleSfx                ; $821D  the effect playing
    lsr     titleSfxRequest         ; $821F  $01 requested
    bcs     TitleSfx_NameCursorFar  ; $8221
    lsr     a                       ; $8223  $01 playing
    bcs     TitleSfx_NameCursorStepFar ; $8224
    lsr     titleSfxRequest         ; $8226  $02 requested
    bcs     TitleSfx_LetterCursor   ; $8228
    lsr     a                       ; $822A  $02 playing
    bcs     TitleSfx_Vibrato        ; $822B
    lsr     titleSfxRequest         ; $822D  $04 requested
    bcs     TitleSfx_Select         ; $822F
    lsr     a                       ; $8231  $04 playing
    bcs     TitleSfx_Vibrato        ; $8232
    lsr     titleSfxRequest         ; $8234  $08 requested
    bcs     TitleSfx_Eliminate      ; $8236
    lsr     a                       ; $8238  $08 playing
    bcs     TitleSfx_EliminateStep  ; $8239
    rts                             ; $823B

TitleSfx_Eliminate:
    lda     #$1F                    ; $823C  $1F frames
    jsr     TitleSfx_Start          ; $823E
    lda     #$8A                    ; $8241  both pulses sweep down
    sta     SQ1_SWEEP               ; $8243
    sta     SQ2_SWEEP               ; $8246

TitleSfx_EliminateStep:
    lda     titleSfxTimer           ; $8249  a step every 2 frames:
    lsr     a                       ; $824B
    tay                             ; $824C
    lda     TitleSfxVolumes,y       ; $824D  the volume,
    sta     SQ1_VOL                 ; $8250
    sta     SQ2_VOL                 ; $8253
    sta     SQ1_LO                  ; $8256  also pulse 1's timer low,
    sec                             ; $8259  pulse 2's 4 lower
    sbc     #$04                    ; $825A
    sta     SQ2_LO                  ; $825C
    lda     #$08                    ; $825F  high 0
    sta     SQ1_HI                  ; $8261
    sta     SQ2_HI                  ; $8264
    jmp     TitleSfx_Tick           ; $8267

; ---------------------------------------------------------------------------
; TitleMusic_Update
;
; The title music: start the song part in titleSongRequest ($01 also
; resets the intro's swell), else play the current part
; (TitleMusic_PlayNotes).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_Update:
    lda     titleSongRequest        ; $826A  part 1 (the intro) requested?
    and     #$01                    ; $826C
    bne     @intro                  ; $826E
    lda     titleSongRequest        ; $8270  another part?
    beq     @play                   ; $8272
    jmp     TitleMusic_StartPart    ; $8274  start it

@intro:
    ldx     #$20                    ; $8277  the intro: both swells from $20
    stx     titleSq2Swell           ; $8279
    stx     titleEchoSwell          ; $827C
    jmp     TitleMusic_StartPart    ; $827F  start it

@play:
    lda     titleMusicPart          ; $8282  a part playing?
    beq     TitleMusic_Silence_Done ; $8284
    jmp     TitleMusic_PlayNotes    ; $8286  yes: a frame of it

; ---------------------------------------------------------------------------
; TitleMusic_NextPart
;
; The part's phrase list has ended: part $01 goes on to $02, $02 to $04,
; $04 to $08, $08 to $10 and $10 back to $02; anything else (the $80 of
; Title_CheckStart, whose list is empty) stops the music.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_NextPart:
    lda     titleMusicPart          ; $8289  $01-$10?
    and     #$1F                    ; $828B
    bne     TitleMusic_ChooseNextPart ; $828D
    ldx     #$00                    ; $828F  no ($80): stop
    stx     titleMusicPart          ; $8291

; ---------------------------------------------------------------------------
; TitleMusic_Silence
;
; Stop the title music: zero the pulses' and the echo's envelope steps and
; silence the pulse, triangle and noise channels.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_Silence:
    ldx     #$00                    ; $8293  no envelopes,
    stx     titleSq2EnvStep         ; $8295
    stx     titleEchoEnvStep        ; $8298
    stx     titleSq1EnvStep         ; $829B
    stx     TRI_LINEAR              ; $829E  triangle off,
    ldx     #$10                    ; $82A1  noise and pulses silent
    stx     NOISE_VOL               ; $82A3
    stx     SQ1_VOL                 ; $82A6
    stx     SQ2_VOL                 ; $82A9

TitleMusic_Silence_Done:
    rts                             ; $82AC

TitleMusic_ChooseNextPart:
    cmp     #$01                    ; $82AD  $01:
    bne     @not1                   ; $82AF
    lda     #$02                    ; $82B1  $02
    bne     TitleMusic_StartPart    ; $82B3

@not1:
    cmp     #$02                    ; $82B5  $02:
    bne     @not2                   ; $82B7
    lda     #$04                    ; $82B9  $04
    bne     TitleMusic_StartPart    ; $82BB

@not2:
    cmp     #$04                    ; $82BD  $04:
    bne     @not4                   ; $82BF
    lda     #$08                    ; $82C1  $08
    bne     TitleMusic_StartPart    ; $82C3

@not4:
    cmp     #$08                    ; $82C5  $08:
    bne     @not8                   ; $82C7
    lda     #$10                    ; $82C9  $10
    bne     TitleMusic_StartPart    ; $82CB

@not8:
    lda     #$02                    ; $82CD  $10: back to $02

; ---------------------------------------------------------------------------
; TitleMusic_StartPart
;
; Start title song part a (one bit, titleMusicPart): set titleEcho for
; the intro (part 1) and load its first phrase.
;
; In:      a = part bit
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_StartPart:
    sta     titleMusicPart          ; $82CF
    jsr     TitleMusic_Silence      ; $82D1  silence first
    tax                             ; $82D4  the intro?
    and     #$01                    ; $82D5
    beq     @noEcho                 ; $82D7
    ldy     #$01                    ; $82D9  echo on
    bne     @setEcho                ; $82DB

@noEcho:
    ldy     #$00                    ; $82DD  off

@setEcho:
    sty     titleEcho               ; $82DF
    ldy     #$00                    ; $82E2  from the first phrase
    sty     titlePhrase             ; $82E4
    txa                             ; $82E7  the bit's number + 1

@loop:
    iny                             ; $82E8
    lsr     a                       ; $82E9
    bcc     @loop                   ; $82EA
    sty     titleSongPart           ; $82EC

; ---------------------------------------------------------------------------
; TitleMusic_LoadPhrase
;
; Load the part's next phrase from TitleMusic: an 8-byte record of the
; note-length row, the note pointer, the triangle, pulse 1 and noise
; offsets, and the two pulses' envelope offsets; pulse 2 starts at offset
; 0.  An entry of 0 ends the part (TitleMusic_NextPart).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_LoadPhrase:
    ldy     titleSongPart           ; $82EF  the part's
    lda     TitleMusic-1,y          ; $82F2  phrase list offset
    clc                             ; $82F5
    adc     titlePhrase             ; $82F6  + the phrase
    inc     titlePhrase             ; $82F9  (next time the next)
    tay                             ; $82FC
    lda     TitleMusic,y            ; $82FD  the phrase record's offset
    tay                             ; $8300
    beq     TitleMusic_NextPart     ; $8301  0: the part is over
    lda     TitleMusic,y            ; $8303  note length row
    sta     titleDurationBase       ; $8306
    lda     TitleMusic+1,y          ; $8309  note data pointer
    sta     titleNotesPtr           ; $830C
    lda     TitleMusic+2,y          ; $830E
    sta     musicNotesPtr+1         ; $8311  (its high byte shares musicNotesPtr+1)
    lda     TitleMusic+3,y          ; $8313  triangle offset
    sta     titleTriOffset          ; $8316
    lda     TitleMusic+4,y          ; $8318  pulse 1 offset
    sta     titleSq1Offset          ; $831B
    lda     TitleMusic+5,y          ; $831D  noise offset
    sta     titleNoiseOffset        ; $8320
    sta     titleNoiseLoop          ; $8322  (also its loop point)
    lda     TitleMusic+6,y          ; $8325  pulse 2's envelope
    sta     titleSq2EnvBase         ; $8328
    lda     TitleMusic+7,y          ; $832B  pulse 1's envelope
    sta     titleSq1EnvBase         ; $832E
    lda     #$00                    ; $8331  pulse 2 from offset 0,
    sta     titleSq2Offset          ; $8333
    sta     titleEchoEnvStep        ; $8335  no echo yet
    lda     #$01                    ; $8338  every channel's note ends now
    sta     titleSq2Timer           ; $833A
    sta     titleSq1Timer           ; $833C
    sta     titleTriTimer           ; $833E
    sta     titleNoiseTimer         ; $8340
    bne     TitleMusic_PlayNotes    ; $8342

TitleMusic_LoadPhraseFar:
    jmp     TitleMusic_LoadPhrase   ; $8344

; ---------------------------------------------------------------------------
; TitleMusic_PlayNotes
;
; Play one frame of the title song's four channels.  Each counts its note
; down and then reads on: a byte >= $80 sets the channel's note length
; (TitleMusic_NoteLength) and the next byte is read; a byte of 0 ends the
; phrase (pulse 2) or loops the part (noise, to titleNoiseLoop); others are
; pitches (TitlePeriods; $02 is a rest).  The pulses follow
; TitleEnvelopes and waver (vibrato); in the intro, pulse 1 repeats pulse
; 2's note 8 frames later (titleEcho), and both swell (peak volume 3 rising
; to 15 over about 384 frames).  The noise plays TitleDrums.  The pulses
; give way to a title sound effect (titleSfx).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
TitleMusic_PlayNotes:
    lda     titleEcho               ; $8347  the intro's echo:
    beq     @melody                 ; $834A
    lda     titleSfx                ; $834C  (not during an effect)
    bne     @melody                 ; $834E
    inc     titleEchoDelay          ; $8350  8 frames after pulse 2's note:
    lda     titleEchoDelay          ; $8353
    cmp     #$08                    ; $8356
    bne     @melody                 ; $8358
    lda     titleSq2Pitch           ; $835A  the same pitch on pulse 1
    jsr     TitleSq1_PlayNote       ; $835D
    beq     @melody                 ; $8360  a rest
    lda     titleMusicPart          ; $8362  the intro
    and     #$01                    ; $8364
    beq     @echoFull               ; $8366
    lda     titleSq2Swell           ; $8368  still swelling:
    cmp     #$5F                    ; $836B
    bcs     @echoFull               ; $836D
    inc     titleEchoSwell          ; $836F  the echo's swell grows
    inc     titleEchoSwell          ; $8372
    lda     titleEchoSwell          ; $8375
    bne     @setEchoEnv             ; $8378

@echoFull:
