Sound_Engine:
    lda     soundMute               ; $9000  muted (the overworld pause)?
    beq     @run                    ; $9002
; (code below not executed in the test movies)
    lda     #$00                    ; $9004  yes: every channel off
    sta     SND_CHN                 ; $9006
    beq     @done                   ; $9009
; (end of code not executed in the test movies)

@run:
    lda     #$FF                    ; $900B  the frame counter: 4-step, no IRQ
    sta     APU_FRAME               ; $900D
    jsr     Sfx_UpdateDmc           ; $9010  the DMC samples,
    jsr     Sfx_UpdateShared        ; $9013  the shared effects,
    jsr     Sfx_UpdateSq1           ; $9016  pulse 1's,
    jsr     Sfx_UpdateSq2           ; $9019  pulse 2's,
    jsr     Sfx_UpdateNoise         ; $901C  the noise's,
    jsr     Music_Update            ; $901F  then the music
    lda     #$00                    ; $9022  this frame's requests are done
    sta     sfxRequest+3            ; $9024
    sta     sfxRequest+2            ; $9026
    sta     sfxRequest+1            ; $9028
    sta     sfxRequest              ; $902A
    sta     musicRequest            ; $902C
    sta     dmcRequest              ; $902E

@done:
    rts                             ; $9030

; ---------------------------------------------------------------------------
; Sq1_SetEnvelope
;
; Write x to SQ1_VOL and y to SQ1_SWEEP.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq1_SetEnvelope:
    stx     SQ1_VOL                 ; $9031
    sty     SQ1_SWEEP               ; $9034
    rts                             ; $9037

; ---------------------------------------------------------------------------
; Sq2_SetEnvelope
;
; Write x to SQ2_VOL and y to SQ2_SWEEP.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq2_SetEnvelope:
    stx     SQ2_VOL                 ; $9038
    sty     SQ2_SWEEP               ; $903B
    rts                             ; $903E

; ---------------------------------------------------------------------------
; Sq1_PlayNoteEnvelope
;
; Sq1_SetEnvelope, then Sq1_PlayNote.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq1_PlayNoteEnvelope:
    jsr     Sq1_SetEnvelope         ; $903F

; ---------------------------------------------------------------------------
; Sq1_PlayNote
;
; Play pitch a (an even NotePeriods index) on pulse 1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq1_PlayNote:
    ldx     #$00                    ; $9042

; ---------------------------------------------------------------------------
; Sound_PlayNote
;
; Play pitch a (an even NotePeriods index; 0 = rest, nothing written) on
; the channel at x (0 = pulse 1, 4 = pulse 2, 8 = triangle), keeping a
; pulse's timer low byte for its vibrato.
;
; In:      a = pitch, x = channel register offset
; Out:     z set for a rest
; Status:  confirmed
; ---------------------------------------------------------------------------
Sound_PlayNote:
    tay                             ; $9044
    lda     NotePeriods+1,y         ; $9045  the period's low byte
    beq     @done                   ; $9048  0: a rest
    sta     SQ1_LO,x                ; $904A
    cpx     #$00                    ; $904D  pulse 1:
    bne     @checkSq2               ; $904F
    sta     sq1TimerLo              ; $9051  kept for its vibrato
    bne     @high                   ; $9053

@checkSq2:
    cpx     #$04                    ; $9055  pulse 2:
    bne     @high                   ; $9057
    sta     sq2TimerLo              ; $9059  kept

@high:
    lda     NotePeriods,y           ; $905B  the high bits,
    ora     #$08                    ; $905E  with a length counter load
    sta     SQ1_HI,x                ; $9060  (restarts the note)

@done:
    rts                             ; $9063

; ---------------------------------------------------------------------------
; Sq2_PlayNoteEnvelope
;
; Sq2_SetEnvelope, then Sq2_PlayNote.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq2_PlayNoteEnvelope:
    jsr     Sq2_SetEnvelope         ; $9064

; ---------------------------------------------------------------------------
; Sq2_PlayNote
;
; Play pitch a on pulse 2.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq2_PlayNote:
    ldx     #$04                    ; $9067
    bne     Sound_PlayNote          ; $9069

; ---------------------------------------------------------------------------
; Tri_PlayNote
;
; Play pitch a on the triangle.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Tri_PlayNote:
    ldx     #$08                    ; $906B
    bne     Sound_PlayNote          ; $906D

; ---------------------------------------------------------------------------
; Music_NoteDuration
;
; Decode a note byte: bit 0, bit 7 and bit 6 (from high to low) are the
; duration index, looked up in the musicTempo row of NoteDurations.
;
; In:      a = note byte
; Out:     a = frames, x = the note byte (bits 5-1 = pitch index)
; Status:  confirmed
; ---------------------------------------------------------------------------
Music_NoteDuration:
    tax                             ; $906F
    ror     a                       ; $9070  bit 0 into the carry,
    txa                             ; $9071
    rol     a                       ; $9072  then above bits 7-6:
    rol     a                       ; $9073
    rol     a                       ; $9074
    and     #$07                    ; $9075  the duration index (0-7)
    clc                             ; $9077  in the tempo's row
    adc     musicTempo              ; $9078
    tay                             ; $907A
    lda     NoteDurations,y         ; $907B  frames
    rts                             ; $907E

; ---------------------------------------------------------------------------
; Sq1_VibratoSfx
;
; Vibrato on pulse 1 for a sound effect: the period's low byte is sq1TimerLo
; + 2 or - 2 by bit 2 of the shared effect's frames left (sharedSfxTimer;
; the fairy's effect alternates $78 and $74 every 4 frames).  The
; fall-back to sq1SfxTimer never runs: only shared effects call it.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq1_VibratoSfx:
    lda     sharedSfxTimer          ; $907F  a shared effect playing?
    bne     Sq1_VibratoA            ; $9082
; (code below not executed in the test movies)
    lda     sq1SfxTimer             ; $9084  a pulse 1 effect?
    bne     Sq1_VibratoA            ; $9087
; (end of code not executed in the test movies)

; ---------------------------------------------------------------------------
; Sq1_Vibrato
;
; Vibrato on pulse 1, from the harmony note's frames left.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq1_Vibrato:
    lda     harmonyTimer            ; $9089  the note's frames left

Sq1_VibratoA:
    ldx     #$00                    ; $908C  pulse 1, from its base
    ldy     sq1TimerLo              ; $908E
    bne     Sound_Vibrato           ; $9090
; (code below not executed in the test movies)
    lda     sq2SfxTimer             ; $9092  (unreachable)
    bne     Sq2_VibratoA            ; $9095
; (end of code not executed in the test movies)

; ---------------------------------------------------------------------------
; Sq2_Vibrato
;
; Vibrato on pulse 2, from the melody note's frames left.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sq2_Vibrato:
    lda     melodyTimer             ; $9097  the note's frames left

Sq2_VibratoA:
    ldx     #$04                    ; $909A  pulse 2, from its base
    ldy     sq2TimerLo              ; $909C

; ---------------------------------------------------------------------------
; Sound_Vibrato
;
; Set the channel's timer low byte to its base +2 or -2, by bit 2 of the
; frames left (alternating every 4 frames).  The high byte is not written, which
; would restart the waveform and click.
;
; In:      a = frames left, x = channel register offset, y = base timer low
; Status:  confirmed
; ---------------------------------------------------------------------------
Sound_Vibrato:
    sty     titleMusicPart          ; $909E  (titleMusicPart is free scratch here)
    lsr     a                       ; $90A0  bit 2 of the frames left:
    lsr     a                       ; $90A1
    lsr     a                       ; $90A2
    bcs     @up                     ; $90A3
    lda     #$FE                    ; $90A5  clear: base - 2
    clc                             ; $90A7
    adc     titleMusicPart          ; $90A8
    bne     @store                  ; $90AA

@up:
    lda     #$02                    ; $90AC  set: base + 2
    clc                             ; $90AE
    adc     titleMusicPart          ; $90AF

@store:
    sta     SQ1_LO,x                ; $90B1  the low byte only
    rts                             ; $90B4

; ---------------------------------------------------------------------------
; Sound_StopAll
;
; End every sound effect and stop the music.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sound_StopAll:
    lda     #$00                    ; $90B5  no effects:
    sta     sq1Sfx                  ; $90B7
    sta     noiseSfx                ; $90BA
    sta     sharedSfx               ; $90BD
    sta     sharedSfxOnNoise        ; $90C0
    sta     sharedSfxOnSq1          ; $90C3
    jsr     Music_Stop              ; $90C6  and no music
    rts                             ; $90C9
; (unreferenced: $90CA-$90CA, 1 bytes)
    .byte   $4A                                                             ; $90CA

; ---------------------------------------------------------------------------
; Sfx_SweepStep32
;
; Step a sound effect's pitch: return y + a / 32 if sweepUp is set, else
; y - a / 32 (the step at least 1).  Sfx_SweepStep16 and Sfx_SweepStep8
; divide by 16 and 8.  Every caller passes the pitch itself in both a and
; y, so it moves by a fixed fraction of itself each frame (the barrier's
; period falls by 16, then 12, then 8).
;
; In:      a, y = the current value
; Out:     a = the new value
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_SweepStep32:
    lsr     a                       ; $90CB  / 32

Sfx_SweepStep16:
    lsr     a                       ; $90CC  / 16

Sfx_SweepStep8:
    lsr     a                       ; $90CD  / 8
    lsr     a                       ; $90CE
    lsr     a                       ; $90CF
    sta     sweepStep               ; $90D0  the step,
    bne     @apply                  ; $90D3
    inc     sweepStep               ; $90D5  at least 1

@apply:
    lda     sweepUp                 ; $90D8  up?
    beq     @down                   ; $90DB
    tya                             ; $90DD  the value + step
    clc                             ; $90DE
    adc     sweepStep               ; $90DF
    rts                             ; $90E2

@down:
    tya                             ; $90E3  down: - step
    sec                             ; $90E4
    sbc     sweepStep               ; $90E5

SwordNoise:
    rts                             ; $90E8
    .byte   $0B, $09, $0D, $0E, $0F, $0B, $09, $0D, $0E, $0F, $FB, $F9, $9D, $6E, $3F; $90E9

KillVolumes:
    .byte   $95, $5A, $9C, $5D, $9E, $5F                                    ; $90F8

KillNotes:
    .byte   $38, $48, $08, $06, $08, $06                                    ; $90FE

ChimeVolumes:
    .byte   $51, $92, $53, $94, $55, $96, $57, $98, $59, $9A, $5B, $9C, $5D, $9E, $5F; $9104
; (unreferenced: $9113-$9122, 16 bytes)
    .byte   $1E, $28, $32, $3C, $1E, $28, $30, $32, $18, $22, $28, $28, $28, $32, $36, $38; $9113

HurtNoise:
    .byte   $03, $34, $75, $56, $98, $BA, $EC, $FD, $BA                     ; $9123

CrumbleNoise:
    .byte   $05, $3E, $7A, $5C, $9A, $BD, $EE, $FF, $BB                     ; $912C

PulseEnvelope:
    .byte   $90, $91, $91, $91, $92, $92, $92, $93, $93, $93, $94, $94, $94, $95, $95, $95; $9135
    .byte   $96, $96, $96, $97, $97, $97, $98, $98                          ; $9145

NoteDurations:
    .byte   $04, $0C, $08, $10, $18, $20, $05, $06                          ; $914D
    .byte   $04, $0F, $09, $12, $1B, $24, $06, $06                          ; $9155
    .byte   $05, $0F, $0A, $14, $1E, $28, $07, $06                          ; $915D
    .byte   $06, $12, $0C, $18, $24, $30, $08, $10                          ; $9165
    .byte   $07, $15, $0E, $1C, $2A, $38, $13, $12                          ; $916D
    .byte   $07, $15, $0E, $1C, $2A, $38                                    ; $9175

DmcSamples:
    .byte   $09, $0A                                                        ; $917B
    .byte   $CC, $0C                                                        ; $917D
    .byte   $CF, $1C                                                        ; $917F
    .byte   $D6, $18                                                        ; $9181
    .byte   $DC, $14                                                        ; $9183
    .byte   $E1, $18                                                        ; $9185
    .byte   $E7, $0F                                                        ; $9187
    .byte   $EA, $0F                                                        ; $9189

; Two more sample entries ($FB80 and $FC80, 241 bytes each) that no sound
; effect uses.
DmcSamplesUnused:
    .byte   $EE, $0F, $F2, $0F                                              ; $918B

NotePeriods:
    .byte   $03, $57, $00, $00, $02, $A6, $02, $3A, $02, $1A, $01, $FC, $01, $DF, $01, $C4; $918F
    .byte   $01, $AB, $01, $93, $01, $7C, $01, $67, $01, $52, $01, $3F, $01, $2D, $01, $1C; $919F
    .byte   $01, $0C, $00, $FD, $00, $EE, $00, $E1, $00, $D4, $00, $C8, $00, $BD, $00, $B2; $91AF
    .byte   $00, $A8, $00, $9F, $00, $96, $00, $8D, $00, $7E, $00, $76, $00, $70, $03, $27; $91BF
    .byte   $02, $F9, $02, $CF, $02, $80, $02, $5C, $00, $85, $00, $6A, $00, $64, $00, $5F; $91CF
    .byte   $00, $59, $00, $54, $00, $50, $00, $4B, $00, $47, $00, $43, $00, $3F, $00, $3B; $91DF
    .byte   $00, $38, $00, $35, $00, $32, $00, $2F, $00, $2C, $00, $2A, $00, $28, $00, $25; $91EF
    .byte   $00, $23, $00, $21, $00, $1F, $00, $1D, $00, $1C, $00, $1A      ; $91FF

; ---------------------------------------------------------------------------
; Sfx_UpdateDmc
;
; Sound effects on the DMC channel, requested in dmcRequest: bit 0 Link's
; grunt when hurt (Link_TakeDamage, Link_CheckBgInBank, Dark Link's
; sword), bit 1 Ganon's laugh at the game over (Death_LoseLife), played
; as samples 2, 4, 5, 6 and 7, 23 frames apart (laughSample).  QUIRK:
; laughSample starts at 3 and is counted up before each next sample, so
; sample 3 (DmcLaugh2) is never played (seen in a scripted game over: the
; sample starts were $CF, $DC, $E1, $E7, $EA).  Other bits do nothing.
; The samples are in bank 7.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_UpdateDmc:
    ldy     dmcRequest              ; $920B  the request bits
    lda     dmcSfx                  ; $920D  the sample playing
    lsr     dmcRequest              ; $9210  bit 0: Link's grunt?
    bcs     @grunt                  ; $9212
    lsr     dmcRequest              ; $9214  bit 1: the laugh?
    bcs     @laugh                  ; $9216
    lsr     a                       ; $9218  none: the grunt playing?
    bcs     @count                  ; $9219
    lsr     a                       ; $921B  or the laugh?
    bcs     @count                  ; $921C
    jmp     @dmcOff                 ; $921E  no: DMC off

@grunt:
    ldx     #$C0                    ; $9221  the grunt: $C0 frames,
    lda     #$04                    ; $9223  the channel on 4 frames
    sty     dmcSfx                  ; $9225  (dmcSfx 1)
    stx     dmcTimer                ; $9228
    sta     dmcEnableTimer          ; $922B
    bne     @startSample            ; $922E  (always)
; (code below not executed in the test movies)

@laugh:
    sty     dmcSfx                  ; $9230  the laugh (dmcSfx 2): $C0 frames,
    ldx     #$C0                    ; $9233
    stx     dmcTimer                ; $9235
    ldx     #$03                    ; $9238  its next part: 3 (QUIRK: counted up first)
    stx     laughSample             ; $923A
    lda     #$08                    ; $923D  the channel on 8 frames
    bne     @setOnTime              ; $923F

@loop:
    lda     #$05                    ; $9241  the next part: on 5 frames

@setOnTime:
    sta     dmcEnableTimer          ; $9243
    lda     #$18                    ; $9246  23 frames to the next
    sta     laughSampleTimer        ; $9248
; (end of code not executed in the test movies)

@startSample:
    tya                             ; $924B  the sample's start
    asl     a                       ; $924C
    tay                             ; $924D
    lda     DmcSamples,y            ; $924E
    sta     DMC_START               ; $9251
    lda     DmcSamples+1,y          ; $9254  and length
    sta     DMC_LEN                 ; $9257
    lda     #$0F                    ; $925A  rate 15, no loop
    sta     DMC_FREQ                ; $925C
    lda     #$0F                    ; $925F  (restarts the DMC)
    sta     SND_CHN                 ; $9261

@count:
    dec     dmcTimer                ; $9264  count
    beq     @done                   ; $9267  over: done
    lda     dmcSfx                  ; $9269
    cmp     #$01                    ; $926C  the laugh:
    beq     @channel                ; $926E
; (code below not executed in the test movies)
    dec     laughSampleTimer        ; $9270  time for the next part?
    bne     @channel                ; $9273
    inc     laughSample             ; $9275  (3 is skipped)
    ldy     laughSample             ; $9278
    cpy     #$08                    ; $927B  all done after 7
    bcc     @loop                   ; $927D
; (end of code not executed in the test movies)

@channel:
    lda     dmcEnableTimer          ; $927F  the channel's frames on
    beq     @dmcOff                 ; $9282
    dec     dmcEnableTimer          ; $9284  count
    beq     @dmcOff                 ; $9287
    bne     @dmcOn                  ; $9289  still on

@done:
    lda     #$00                    ; $928B
    sta     dmcSfx                  ; $928D

@dmcOff:
    lda     #$0F                    ; $9290  DMC off
    sta     SND_CHN                 ; $9292
    rts                             ; $9295

@dmcOn:
    lda     #$1F                    ; $9296  DMC on
    sta     SND_CHN                 ; $9298
    rts                             ; $929B

; ---------------------------------------------------------------------------
; Sfx_StopSq1AndShared
;
; Pulse 1 effect $01: end the shared and DMC effects, silence pulse 1 and
; the noise channel, and go on with the other requests.  The music takes
; pulse 1 back the same frame.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_StopSq1AndShared:
    ldx     #$00                    ; $929C  no shared effects,
    stx     sfxRequest              ; $929E
    stx     sharedSfxRecent         ; $92A0
    stx     sharedSfx               ; $92A3
    stx     dmcSfx                  ; $92A6
    stx     sharedSfxOnNoise        ; $92A9
    stx     sharedSfxOnSq1          ; $92AC
    ldx     #$10                    ; $92AF  pulse 1 and noise silent
    stx     SQ1_VOL                 ; $92B1
    stx     NOISE_VOL               ; $92B4
    ldx     #$0F                    ; $92B7  DMC off
    stx     SND_CHN                 ; $92B9
    bne     Sfx_UpdateSq1Requests   ; $92BC  on with the other requests

Sfx_ItemDrop:
    lda     #$18                    ; $92BE  $18 frames:
    sta     sq1SfxTimer             ; $92C0
    sty     sq1Sfx                  ; $92C3
    ldx     #$95                    ; $92C6  a note at pitch $52,
    ldy     #$E3                    ; $92C8
    lda     #$52                    ; $92CA
    jsr     Sq1_PlayNoteEnvelope    ; $92CC

Sfx_ItemDropStep:
    lda     sq1SfxTimer             ; $92CF  halfway:
    cmp     #$0C                    ; $92D2
    bne     @step                   ; $92D4
    lda     #$4E                    ; $92D6  pitch $4E
    jsr     Sq1_PlayNote            ; $92D8

@step:
    jmp     Sfx_Sq1Step             ; $92DB  count it down

Sfx_MenuCursor:
    sty     sq1Sfx                  ; $92DE
    lda     #$02                    ; $92E1  2 frames
    sta     sq1SfxTimer             ; $92E3

Sfx_MenuCursorStep:
    ldx     #$9C                    ; $92E6  the cursor's envelope
    ldy     #$82                    ; $92E8
    jsr     Sq1_SetEnvelope         ; $92EA
    ldx     #$90                    ; $92ED  timer low $90
    lda     #$08                    ; $92EF
    jmp     Sfx_Sq1SetTimer         ; $92F1

; ---------------------------------------------------------------------------
; Sfx_UpdateSq1
;
; Sound effects on pulse 1, requested in sfxRequest+3 (one bit each; the
; one playing is in sq1Sfx):
;   $01 Sfx_StopSq1AndShared: no sound of its own; ends the shared and
;       DMC effects (LockedDoor_Ai)
;   $02 Sfx_ItemDrop: an item dropped by a killed enemy (Enemy_DropItem;
;       also Link_Control and the ending's typing)
;   $04 Sfx_KillOrChime: an enemy killed (Enemy_Kill)
;   $08 Sfx_KillOrChime: the sword chime, for the sword beam or picking up
;       an item (Item_Collect...)
;   $10 Sfx_MenuCursor: a menu cursor moving (pause, level up, continue)
;   $20 Sfx_Elevator: an elevator moving (Elevator_Ai)
;   $40 Sfx_LowHealth: the low life beep (Mode_SideView)
;   $80 nothing.
; Gives way while a shared effect has pulse 1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_UpdateSq1:
    ldy     sfxRequest+3            ; $92F4  the requests (y: the effect started)
    lda     sq1Sfx                  ; $92F6  the effect playing
    lsr     sfxRequest+3            ; $92F9  $01: stop?
    bcs     Sfx_StopSq1AndShared    ; $92FB

Sfx_UpdateSq1Requests:
    ldx     sharedSfxOnSq1          ; $92FD  a shared effect has pulse 1?
    beq     @requests               ; $9300
    ldx     #$00                    ; $9302  yes: give way
    stx     sq1Sfx                  ; $9304
    rts                             ; $9307

@requests:
    lsr     a                       ; $9308  each bit in turn, playing (a) or requested:
    lsr     a                       ; $9309  $02 playing:
    bcs     Sfx_ItemDropStep        ; $930A
    lsr     sfxRequest+3            ; $930C  $02 requested: start
    bcs     Sfx_ItemDrop            ; $930E
    lsr     sfxRequest+3            ; $9310  $04 requested
    bcs     Sfx_KillOrChime         ; $9312
    lsr     a                       ; $9314  $04 playing
    bcs     Sfx_KillOrChimeStep     ; $9315
    lsr     sfxRequest+3            ; $9317  $08 requested
    bcs     Sfx_KillOrChime         ; $9319
    lsr     a                       ; $931B  $08 playing
    bcs     Sfx_KillOrChimeStep     ; $931C
    lsr     a                       ; $931E  $10 playing
    bcs     Sfx_MenuCursorStep      ; $931F
    lsr     sfxRequest+3            ; $9321  $10 requested
    bcs     Sfx_MenuCursor          ; $9323
    lsr     a                       ; $9325  $20 playing
    bcs     Sfx_ElevatorStep        ; $9326
    lsr     sfxRequest+3            ; $9328  $20 requested
    bcs     Sfx_Elevator            ; $932A
    lsr     a                       ; $932C  $40 playing
    bcs     Sfx_Sq1Step             ; $932D
    lsr     sfxRequest+3            ; $932F  $40 requested
    bcs     Sfx_LowHealth           ; $9331
    rts                             ; $9333

Sfx_KillOrChime:
    sty     sq1Sfx                  ; $9334
    lda     sq1Sfx                  ; $9337  the chime ($08)?
    and     #$08                    ; $933A
    bne     @chime                  ; $933C
    lda     #$14                    ; $933E  kill: $14 frames
    bne     @setTimer               ; $9340

@chime:
    lda     #$3B                    ; $9342  chime: $3B frames

@setTimer:
    sta     sq1SfxTimer             ; $9344
    lda     #$8A                    ; $9347  a sweep down
    sta     SQ1_SWEEP               ; $9349

Sfx_KillOrChimeStep:
    lda     sq1SfxTimer             ; $934C  a step every 4 frames
    lsr     a                       ; $934F
    lsr     a                       ; $9350
    tay                             ; $9351
    lda     sq1Sfx                  ; $9352  the chime?
    and     #$08                    ; $9355
    bne     @chimeStep              ; $9357
    lda     KillVolumes,y           ; $9359  kill: volume
    sta     SQ1_VOL                 ; $935C
    lda     KillNotes,y             ; $935F  and pitch by step
    bne     @play                   ; $9362

@chimeStep:
    lda     ChimeVolumes,y          ; $9364  chime: volume by step,
    sta     SQ1_VOL                 ; $9367
    tya                             ; $936A  pitch alternating
    lsr     a                       ; $936B
    bcc     @lowNote                ; $936C
    lda     #$54                    ; $936E  $54
    bne     @play                   ; $9370

@lowNote:
    lda     #$62                    ; $9372  $62

@play:
    jsr     Sq1_PlayNote            ; $9374
    jmp     Sfx_Sq1Step             ; $9377  count it down

Sfx_Elevator:
    lda     #$0C                    ; $937A  $0C frames
    sta     sq1SfxTimer             ; $937C
    sty     sq1Sfx                  ; $937F
    ldx     #$1A                    ; $9382  its envelope
    ldy     #$7F                    ; $9384
    jsr     Sq1_SetEnvelope         ; $9386

Sfx_ElevatorStep:
    lda     sq1SfxTimer             ; $9389  the first 6 frames:
    cmp     #$06                    ; $938C
    bcc     @second                 ; $938E
    ldx     #$FF                    ; $9390  timer low $FF,
    bne     @setHigh                ; $9392

@second:
    ldx     #$00                    ; $9394  then $00

@setHigh:
    lda     #$0D                    ; $9396  high $0D

Sfx_Sq1SetTimer:
    stx     SQ1_LO                  ; $9398
    sta     SQ1_HI                  ; $939B

Sfx_Sq1Step:
    dec     sq1SfxTimer             ; $939E  count down:
    bne     @done                   ; $93A1  not over
    lda     #$00                    ; $93A3  over:
    sta     sq1Sfx                  ; $93A5
    lda     #$90                    ; $93A8  pulse 1 silent
    sta     SQ1_VOL                 ; $93AA

@done:
    rts                             ; $93AD

Sfx_LowHealth:
    sty     sq1Sfx                  ; $93AE
    lda     #$30                    ; $93B1  $30 frames
    sta     sq1SfxTimer             ; $93B3
    ldx     #$96                    ; $93B6  its envelope
    ldy     #$7F                    ; $93B8
    jsr     Sq1_SetEnvelope         ; $93BA
    ldx     #$60                    ; $93BD  timer $060 + high bits $70
    lda     #$70                    ; $93BF
    bne     Sfx_Sq1SetTimer         ; $93C1

; ---------------------------------------------------------------------------
; Sfx_TakeOverMusic
;
; For an effect that needs both pulses: stop the music and every other
; effect, and silence the noise and triangle channels.
;
; In:      y = the effect (sq2Sfx)
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_TakeOverMusic:
    sty     sq2Sfx                  ; $93C3
    lda     #$00                    ; $93C6  no other effects,
    sta     sq1Sfx                  ; $93C8
    sta     noiseSfx                ; $93CB
    sta     sharedSfx               ; $93CE
    sta     sharedSfxOnNoise        ; $93D1
    sta     sharedSfxOnSq1          ; $93D4
    sta     musicPlaying            ; $93D7  no music,
    lda     #$10                    ; $93DA  noise silent,
    sta     NOISE_VOL               ; $93DC
    lda     #$00                    ; $93DF  triangle silent
    sta     TRI_LINEAR              ; $93E1
    rts                             ; $93E4

Sfx_FallInPit:
    sty     sq2Sfx                  ; $93E5
    jsr     Sound_StopAll           ; $93E8  everything else stops
    lda     #$79                    ; $93EB  $79 frames
    sta     sq2SfxTimer             ; $93ED
    ldx     #$9F                    ; $93F0  a falling note at pitch $58
    ldy     #$C5                    ; $93F2
    lda     #$58                    ; $93F4
    jsr     Sq2_PlayNoteEnvelope    ; $93F6

Sfx_FallInPitStep:
    lda     sq2SfxTimer             ; $93F9  the last frame:
    cmp     #$01                    ; $93FC
    bne     @step                   ; $93FE
    lda     #$22                    ; $9400  pitch $22
    jsr     Sq2_PlayNote            ; $9402

@step:
    jmp     Sfx_Sq2StepFar          ; $9405  count it down

; ---------------------------------------------------------------------------
; Sfx_UpdateSq2
;
; Sound effects on pulse 2, requested in sfxRequest+2 (one bit each; the
; one playing is in sq2Sfx):
;   $01 Sfx_FallInPit: Link falling into a pit (Mode_FallStart); stops
;       every other sound first (Sound_StopAll)
;   $02 Sfx_Encounter: an encounter pulling Link into battle; uses both
;       pulses, stops the music (Sfx_TakeOverMusic) and ends by starting
;       the battle music ($04)
;   $04 Sfx_LeaveBattle: leaving a battle scene
;   $08 Sfx_SpellMenu: the spell menu or a dialog opening (Menu_TextReady,
;       Townsperson_Draw)
;   $10 Sfx_Tink: a deflected shot (Projectile_Deflect, HelmetheadHead_Ai)
;   $20 Sfx_Swamp: walking in a swamp (Link_MoveX)
;   $40, $80 nothing.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Sfx_UpdateSq2:
    ldy     sfxRequest+2            ; $9408  the requests (y: the effect started)
    lda     sq2Sfx                  ; $940A  the effect playing
    lsr     sfxRequest+2            ; $940D  $01 requested: start
    bcs     Sfx_FallInPit           ; $940F
    lsr     a                       ; $9411  $01 playing
    bcs     Sfx_FallInPitStep       ; $9412
    lsr     sfxRequest+2            ; $9414  $02 requested
    bcs     Sfx_Encounter           ; $9416
    lsr     a                       ; $9418  $02 playing
    bcs     Sfx_EncounterStep       ; $9419
    lsr     sfxRequest+2            ; $941B  $04 requested
    bcs     @leaveBattle            ; $941D
    lsr     a                       ; $941F  $04 playing
    bcs     @leaveBattleStep        ; $9420
    jmp     Sfx_UpdateSq2High       ; $9422  the higher bits

@leaveBattle:
    jmp     Sfx_LeaveBattle         ; $9425

@leaveBattleStep:
    jmp     Sfx_LeaveBattleStep     ; $9428

Sfx_Encounter:
    jsr     Sfx_TakeOverMusic       ; $942B  both pulses:
    lda     #$50                    ; $942E  $50 frames,
    ldx     #$8F                    ; $9430  from pitch $8F
    sta     sq2SfxTimer             ; $9432
    stx     sq2SfxPitch             ; $9435
    ldx     #$5E                    ; $9438  both pulses' envelope
    ldy     #$81                    ; $943A
    jsr     Sq1_SetEnvelope         ; $943C
    jsr     Sq2_SetEnvelope         ; $943F
    lda     #$00                    ; $9442  the period falling (pitch rising)
    sta     sweepUp                 ; $9444

Sfx_EncounterStep:
    lda     sq2SfxTimer             ; $9447  halfway ($28 left):
    cmp     #$28                    ; $944A
    bne     @sweep                  ; $944C
    lda     #$01                    ; $944E  then rising (pitch falling)
    sta     sweepUp                 ; $9450

@sweep:
    lda     sq2SfxPitch             ; $9453  sweep by 1/16 each frame
    tay                             ; $9456
    jsr     Sfx_SweepStep16         ; $9457
    sta     sq2SfxPitch             ; $945A  the period:
    rol     a                       ; $945D  x 4 (low byte)
