    rol     a                       ; $94C5
    sta     SQ2_LO                  ; $94C6
    rol     a                       ; $94C9  high bits
    and     #$03                    ; $94CA
    ora     #$08                    ; $94CC
    sta     SQ2_HI                  ; $94CE
