    beq     @envelope2F             ; $9CB8
    lda     #$18                    ; $9CBA  envelope from step $18
    bne     @setEnvelope            ; $9CBC

@envelope2F:
    lda     #$2F                    ; $9CBE  others: from $2F

@setEnvelope:
    sta     sq2EnvelopeStep         ; $9CC0

@melodyFrame:
